var a=`1411-lu-pulu`;var i=`world-1411`;var o=`TO`;var t=`oceania`;var l=4;var s=74;var u={en:`Lu Pulu`,ua:`Лу пулу`};var c={en:`Tongan lu pulu combines corned beef, onion and coconut cream in a leaf parcel. This version replaces unavailable taro leaves with spinach and banana leaf.`,ua:`Тонганське лу пулу поєднує солонину, цибулю та кокосові вершки в листяному пакунку. Тут відсутнє листя таро замінено шпинатом і банановим листям.`};var r=[{en:`Heat oven to 180°C. Drain the canned corned beef and break into coarse chunks. Thinly slice onion.`,ua:`Розігрійте духовку до 180°C. Злийте рідину із солонини та розділіть її на великі шматочки. Тонко наріжте цибулю.`,t:[`slicing`],m:8,i:[[`corned-beef`,450,`g`],[`yellow-onion`,180,`g`]]},{en:`Briefly wilt spinach in a pan, squeeze excess liquid, then toss with the corned beef and onion.`,ua:`Коротко припустіть шпинат на сковороді, відіжміть зайву рідину й змішайте із солониною та цибулею.`,t:[`sauteing`,`mixing`],m:6,i:[[`spinach`,350,`g`]]},{en:`Line a casserole dish with food-safe banana leaves, spoon the mixture in and pour over coconut cream; close the leaves or cover tightly with a lid.`,ua:`Вистеліть форму харчовим банановим листям, викладіть начинку та залийте кокосовими вершками; загорніть листя або щільно накрийте кришкою.`,t:[`leaf-wrapping`],m:10,i:[[`banana-leaf`,5,`leaf`],[`coconut-cream`,350,`ml`]]},{en:`Bake covered for 45–55 minutes until thoroughly hot and bubbling. Unwrap cautiously and serve with cooked root vegetables.`,ua:`Запікайте накритим 45–55 хвилин до повного прогрівання й активного булькання. Обережно розгорніть і подавайте з готовими коренеплодами.`,t:[`baking`],m:50,i:[]}];var h={slug:a,id:i,country:`TO`,region:t,servings:4,minutes:74,title:u,text:c,steps:r};export{o as country,h as default,i as id,s as minutes,t as region,l as servings,a as slug,r as steps,c as text,u as title};